/* ---------------- SetPedestrianTurn (src/pilot/SetPedestrianTurn.c) ---------------- */
void SetPedestrianTurn(PEDESTRIAN *p, int turn) {
    int dir;
    int speed;
    dir = (p->dir.vy + turn) & 0xFFF;
    p->dir.vy = dir;
    dir += 0x800;
    p->pos.vx -= p->vel.vx;
    p->pos.vz -= p->vel.vz;
    speed = p->speed;
    p->vel.vx = (speed * rcossin_tbl[(dir & 0xFFF) * 2]) >> 12;
    p->vel.vz = (speed * rcossin_tbl[(dir & 0xFFF) * 2 + 1]) >> 12;
}

